/** A cycle a depth-first search found among the dependencies. */
export class CycleError extends Error {
  /**
   * @param {string[]} cycle - the names from the re-entered task through the search stack, back to it.
   */
  constructor(cycle) {
    super(`cycle: ${cycle.join(' -> ')}`)
    this.name = 'CycleError'
    this.cycle = cycle
  }
}

/**
 * The first cycle a depth-first search finds, starting from each task in ascending name
 * order and walking each task's dependencies in ascending name order.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[]|null} the cycle's names, ending with a repeat of the first, or null.
 */
function findCycle(tasks) {
  const state = new Map()
  const stack = []

  function visit(name) {
    state.set(name, 'active')
    stack.push(name)
    const deps = [...tasks.get(name).needs].sort()
    for (const dep of deps) {
      const depState = state.get(dep)
      if (depState === 'active') {
        const index = stack.indexOf(dep)
        return [...stack.slice(index), dep]
      }
      if (depState === undefined) {
        const cycle = visit(dep)
        if (cycle) return cycle
      }
    }
    stack.pop()
    state.set(name, 'done')
    return null
  }

  for (const name of [...tasks.keys()].sort()) {
    if (state.get(name) === undefined) {
      const cycle = visit(name)
      if (cycle) return cycle
    }
  }
  return null
}

/**
 * The tasks in run order: repeatedly the lexicographically smallest task whose
 * dependencies have all been emitted.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[]} the names in run order.
 * @throws {CycleError} when the dependencies contain a cycle.
 */
export function order(tasks) {
  const cycle = findCycle(tasks)
  if (cycle) throw new CycleError(cycle)

  const remaining = new Set(tasks.keys())
  const emitted = new Set()
  const out = []
  while (remaining.size > 0) {
    const ready = [...remaining].filter(name => tasks.get(name).needs.every(need => emitted.has(need))).sort()
    if (ready.length === 0) break
    remaining.delete(ready[0])
    emitted.add(ready[0])
    out.push(ready[0])
  }
  return out
}
"}

